    'ກົດລິ້ງນີ້ເພື່ອໃຫ້ Google Maps ນຳທາງມາຮ້ານຈາກບ່ອນທ່ານຢູ່:' => 'Bấm liên kết này, Google Maps sẽ chỉ đường đến cửa hàng từ chỗ bạn:',
