    'ລົບກວນຝາກຊື່ ແລະ ເບີໂທໄວ້ ເພື່ອໃຫ້ພວກເຮົາໂທກັບໄດ້.' => 'Vui lòng để lại tên và số điện thoại để chúng tôi gọi lại.',
    'ລົບກວນຝາກຊື່ ແລະ ເບີໂທໄວ້ ທີມງານຈະໂທກັບພາຍໃນ 24 ຊົ່ວໂມງ.' => 'Vui lòng để lại tên và số điện thoại — chúng tôi sẽ gọi lại trong vòng 24 giờ.',
    'ລາຄາຂຶ້ນກັບປະເພດຮ້ານ, ຈຳນວນເຄື່ອງ ແລະ ອຸປະກອນທີ່ຕ້ອງການ — ທີມງານຈະສົ່ງໃບສະເໜີລາຄາທີ່ເໝາະກັບງົບປະມານຂອງທ່ານ.' => 'Giá tùy theo loại cửa hàng, số lượng máy và thiết bị cần dùng — chúng tôi sẽ gửi báo giá phù hợp với ngân sách của bạn.',
    'ອຸປະກອນ POS ທີ່ພວກເຮົາມີ: %s. ເບິ່ງລາຍລະອຽດໄດ້ທີ່ໜ້າ "ອຸປະກອນ POS".' => 'Thiết bị POS chúng tôi có: %s. Xem chi tiết tại trang "Thiết bị POS".',
    'ພວກເຮົາມີລະບົບ POS ສຳລັບ: %s. ຮ້ານຂອງທ່ານເປັນປະເພດໃດ, ມີຈັກສາຂາ?' => 'Chúng tôi có hệ thống POS cho: %s. Cửa hàng của bạn thuộc loại nào, có mấy chi nhánh?',
