    'ສະບາຍດີ 🙏 ຢາກໄດ້ລະບົບ POS, ອຸປະກອນ ຫຼື ເວັບໄຊ ສຳລັບຮ້ານແບບໃດ? ຖາມໄດ້ເລີຍ.' => 'Xin chào 🙏 Bạn cần hệ thống POS, thiết bị hay website cho loại cửa hàng nào? Cứ hỏi nhé.',
    'ຍິນດີຊ່ວຍເຫຼືອ 🙏 ມີຫຍັງສົງໄສ ຖາມໄດ້ຕະຫຼອດ.' => 'Rất vui được hỗ trợ 🙏 Có gì thắc mắc cứ hỏi bất cứ lúc nào.',
