    'ພັດທະນາລະບົບຂາຍໜ້າຮ້ານ POS ໃຫ້ເໝາະກັບທຸລະກິດຂອງທ່ານ: ຂາຍ, ສະຕັອກ, ລາຍງານ, ຫຼາຍສາຂາ ພ້ອມຕິດຕັ້ງ ແລະ ສອນພະນັກງານຈົນໃຊ້ງານເປັນ.' => 'Phát triển hệ thống POS phù hợp với doanh nghiệp của bạn: bán hàng, kho, báo cáo, nhiều chi nhánh — kèm cài đặt và đào tạo nhân viên đến khi dùng thành thạo.',
    'ເວັບບໍລິສັດ / ຮ້ານຄ້າອອນລາຍ' => 'Website công ty / cửa hàng trực tuyến',
    'ອອກແບບ ແລະ ພັດທະນາເວັບໄຊບໍລິສັດ, ເວັບຂາຍສິນຄ້າອອນລາຍ ແລະ ລະບົບຫຼັງບ້ານ ສວຍງາມ ໂຫຼດໄວ ໃຊ້ງານງ່າຍທັງໃນຄອມ ແລະ ມືຖື.' => 'Thiết kế và phát triển website công ty, cửa hàng trực tuyến và hệ thống quản trị — đẹp, nhanh, dễ dùng trên máy tính và điện thoại.',
    'ພັດທະນາ Mobile App' => 'Phát triển ứng dụng di động',
    'ແອັບ Android & iOS' => 'Ứng dụng Android & iOS',
    'ສ້າງແອັບມືຖື Android ແລະ iOS ສຳລັບທຸລະກິດ ເຊື່ອມຂໍ້ມູນກັບລະບົບ POS ແລະ ເວັບໄຊ ເບິ່ງຍອດຂາຍ ແລະ ຈັດການຮ້ານໄດ້ທຸກບ່ອນ.' => 'Xây dựng ứng dụng Android và iOS cho doanh nghiệp, kết nối với POS và website — xem doanh số và quản lý cửa hàng ở mọi nơi.',
    'ບໍລິການຫຼັງການຂາຍ 24 ຊົ່ວໂມງ' => 'Dịch vụ hậu mãi 24 giờ',
    'ແກ້ໄຂໃຫ້ທຸກບັນຫາ' => 'Xử lý mọi vấn đề',
    'ທີມງານພ້ອມດູແລຕະຫຼອດ 24 ຊົ່ວໂມງ ທຸກມື້ ລະບົບມີບັນຫາຫຍັງ ພວກເຮົາແກ້ໄຂໃຫ້ທັນທີ ທັງອອນລາຍ ແລະ ລົງພື້ນທີ່ ບໍ່ປະຖິ້ມລູກຄ້າ.' => 'Đội ngũ hỗ trợ 24 giờ mỗi ngày. Hệ thống gặp vấn đề gì, chúng tôi xử lý ngay — trực tuyến hoặc tại chỗ, không bỏ rơi khách hàng.',
    'ເຮັດໃຫ້ຕາມຄວາມຕ້ອງການ' => 'Làm theo yêu cầu',
    'ລູກຄ້າຕ້ອງການແນວໃດ ເຮັດໃຫ້ໄດ້' => 'Khách cần gì, chúng tôi làm được',
    'ລູກຄ້າຕ້ອງການລະບົບແບບໃດ ພວກເຮົາສາມາດເຮັດໃຫ້ໄດ້ ອອກແບບ ແລະ ປັບແຕ່ງຟັງຊັນຕາມຄວາມຕ້ອງການຂອງທຸລະກິດທ່ານແທ້ໆ.' => 'Bạn cần hệ thống nào, chúng tôi làm được — thiết kế và tùy chỉnh chức năng theo đúng nhu cầu doanh nghiệp.',
