    'ບໍ່ພົບສິນຄ້ານີ້ ຫຼື ຢຸດຂາຍແລ້ວ' => 'Không tìm thấy sản phẩm hoặc đã ngừng bán',
    'ລະບົບຂາຍໜ້າຮ້ານສຳຜັດງ່າຍ ສຳລັບຮ້ານກາເຟ, ຊານົມໄຂ່ມຸກ ແລະ ເຄື່ອງດື່ມທຸກປະເພດ' => 'Hệ thống bán hàng cảm ứng dễ dùng cho quán cà phê, trà sữa và mọi loại đồ uống',
    'ລະບົບ POS ຮ້ານເຄື່ອງດື່ມ ແລະ ຄາເຟ ອອກແບບມາເພື່ອຄວາມໄວ ແລະ ຄວາມຖືກຕ້ອງ: ຮັບອໍເດີໜ້າຮ້ານໄດ້ໄວ, ເລືອກລະດັບຄວາມຫວານ, ນ້ຳກ້ອນ ແລະ ທັອບປິ້ງໄດ້ລະອຽດ, ພິມໃບສັ່ງເຂົ້າບາຣ໌ນ້ຳອັດຕະໂນມັດ, ຕັ້ງໂປຣໂມຊັ່ນ, ແລະ ເບິ່ງຍອດຂາຍ Real-time ຜ່ານມືຖື.' => 'POS cho quán đồ uống và cà phê, nhanh và chính xác: nhận order nhanh, chọn độ ngọt, đá, topping, tự in phiếu quầy pha chế, khuyến mãi và xem doanh số theo thời gian thực trên điện thoại.',
    'ໜ້າຈໍຂາຍໜ້າຮ້ານສຳຜັດງ່າຍ ເມນູພາບງາມ ເລືອກທັອບປິ້ງ ແລະ ລະດັບຄວາມຫວານ' => 'Màn hình bán hàng cảm ứng, menu hình ảnh, chọn topping và độ ngọt',
    'ເຄື່ອງ POS Dual Screen Touchscreen, ປິ້ນເຕີໃບບິນ ແລະ ລິ້ນຊັກເກັບເງິນ' => 'Máy POS cảm ứng hai màn hình, máy in hóa đơn và két tiền',
    'ໂປຣແກຣມ POS ທັນສະໄໝ ຮອງຮັບຈໍສຳຜັດ Smart Touch ແລະ ແຍກໂຕະ' => 'Phần mềm POS hiện đại, hỗ trợ cảm ứng và quản lý bàn',
    'ລະບົບຄິດເງິນ ແລະ ອອກໃບບິນພາສາລາວສະດວກວ່ອງໄວ' => 'Thanh toán nhanh, in hóa đơn tiếng Lào',
    'ຮັບອໍເດີ ແລະ ຄິດເງິນໄວຂຶ້ນ 3 ເທົ່າ' => 'Nhận order và thanh toán nhanh gấp 3',
    'ໜ້າຈໍສຳຜັດຂະໜາດໃຫຍ່ ເມນູແບ່ງໝວດຊັດເຈນ ກົດສັ່ງໄດ້ໄວ ລູກຄ້າບໍ່ຕ້ອງລໍຖ້າຄິວດົນ ຫຼຸດຄວາມຜິດພາດໃນການສັ່ງເຄື່ອງດື່ມ.' => 'Màn hình cảm ứng lớn, menu phân loại rõ, order nhanh, khách không phải chờ lâu, giảm sai sót.',
    'ພິມບິນເຂົ້າບາຣ໌ນ້ຳອັດຕະໂນມັດ ບໍ່ມີອໍເດີຕົກຫຼົ່ນ' => 'Tự in phiếu quầy pha chế, không sót order',
    'ເມື່ອແຄັດເຊຍກົດຮັບອໍເດີ, ລະບົບຈະສົ່ງລາຍການໄປພິມທີ່ເຄົາເຕີ້ຊົງນ້ຳທັນທີ ພະນັກງານຊົງນ້ຳເຮັດວຽກໄດ້ຕໍ່ເນື່ອງ ບໍ່ຕ້ອງຮ້ອງບອກ.' => 'Khi thu ngân xác nhận order, phiếu in ngay tại quầy pha chế, nhân viên làm liên tục không cần gọi to.',
    'ຕັ້ງໂປຣໂມຊັ່ນເອງ ລະບົບຄິດສ່ວນຫຼຸດໃຫ້ອັດຕະໂນມັດ' => 'Tự đặt khuyến mãi, hệ thống tự tính giảm giá',
    'ຕັ້ງສ່ວນຫຼຸດຕາມສິນຄ້າ ຫຼື ໝວດ ພ້ອມວັນໝົດອາຍຸ ລະບົບຄິດລາຄາໃຫ້ເອງຕອນຂາຍ ແລະ ປິດໂປຣເອງເມື່ອໝົດເວລາ.' => 'Đặt giảm giá theo sản phẩm hoặc danh mục kèm ngày hết hạn, hệ thống tự áp giá khi bán và tự tắt khi hết hạn.',
    'ເບິ່ງຍອດຂາຍ ແລະ ກຳໄລ Real-time ຜ່ານມືຖື' => 'Xem doanh số và lợi nhuận theo thời gian thực trên điện thoại',
    'ເຈົ້າຂອງຮ້ານບໍ່ຈຳເປັນຕ້ອງຢູ່ຮ້ານຕະຫຼອດເວລາ ສາມາດກວດເບິ່ງຍອດຂາຍ, ຈຳນວນບິນ, ເມນູຂາຍດີ ແລະ ກຳໄລສຸດທິໄດ້ 24 ຊົ່ວໂມງ.' => 'Chủ quán không cần ở cửa hàng suốt — xem doanh số, số hóa đơn, món bán chạy và lợi nhuận 24 giờ.',
    'ປ້ອງກັນເງິນຕົກເຮ່ຍ ແລະ ກວດສອບຍອດເງິນໂປ່ງໃສ' => 'Chống thất thoát tiền, kiểm tra minh bạch',
    'ບັນທຶກທຸກການຮັບເງິນ, ແຍກກະການຂາຍ (Shift), ລັອກສິດການຍົກເລີກບິນ, ກວດສອບຍອດເງິນໃນລິ້ນຊັກໄດ້ຕະຫຼອດ.' => 'Ghi lại mọi khoản thu, chia ca bán hàng, khóa quyền hủy hóa đơn, kiểm tra két tiền bất cứ lúc nào.',
    'ຮອງຮັບ Option ເສີມ: ລະດັບຄວາມຫວານ (0%, 25%, 50%, 100%), ນ້ຳກ້ອນ, ທັອບປິ້ງ (ໄຂ່ມຸກ, ວຸ້ນ, ພຸດດິ້ງ)' => 'Tùy chọn thêm: độ ngọt (0%, 25%, 50%, 100%), đá, topping (trân châu, thạch, pudding)',
    'ລະບົບເປີດໂຕະ, ພັກບິນ, ແຍກບິນ ແລະ ລວມບິນສຳລັບລູກຄ້ານັ່ງກິນໃນຮ້ານ' => 'Mở bàn, giữ hóa đơn, tách và gộp hóa đơn cho khách dùng tại chỗ',
    'ພິມໃບບິນພາສາລາວ ພ້ອມໂລໂກ້ຮ້ານຄ້າ' => 'In hóa đơn tiếng Lào kèm logo cửa hàng',
    'ຮອງຮັບປິ້ນເຕີບາຣ໌ນ້ຳທັງແບບ LAN, Wi-Fi ແລະ Bluetooth' => 'Hỗ trợ máy in quầy pha chế LAN, Wi-Fi và Bluetooth',
    'ລະບົບສະສົມຄະແນນລູກຄ້າ ແລະ ສະມາຊິກ ເພີ່ມຍອດຂາຍຊ້ຳ' => 'Tích điểm và thành viên, tăng khách quay lại',
    'ເຮັດວຽກໄດ້ທັງ Offline (ເນັດຫຼຸດຍັງຂາຍຕໍ່ໄດ້) ແລະ Online Sync ຂໍ້ມູນ' => 'Hoạt động ngoại tuyến (mất mạng vẫn bán) và đồng bộ trực tuyến',
    'ລະບົບຂາຍໜ້າຮ້ານມິນິມາດ ສະແກນບາໂຄດໄວ ຈັດການສະຕັອກຫຼາຍພັນລາຍການ' => 'POS cửa hàng tiện lợi, quét mã vạch nhanh, quản lý hàng nghìn mặt hàng',
    'ລະບົບ POS ຮ້ານມິນິມາດ ອອກແບບມາຮອງຮັບການຂາຍສິນຄ້າອຸປະໂພກ-ບໍລິໂພກຂະໜາດໃຫຍ່: ສະແກນບາໂຄດໄວ, ຈັດການສິນຄ້າຫຼາຍກວ່າ 50,000+ ລາຍການ, ຄຸ້ມຄອງສະຕັອກ Real-time, ແຈ້ງເຕືອນສິນຄ້າໃກ້ໝົດ, ແລະ ຮອງຮັບຫຼາຍສະກຸນເງິນ.' => 'POS cửa hàng tiện lợi cho lượng lớn hàng tiêu dùng: quét mã nhanh, hơn 50.000 mặt hàng, tồn kho thời gian thực, cảnh báo sắp hết hàng, nhiều loại tiền.',
    'ໜ້າຈໍຂາຍໜ້າຮ້ານມິນິມາດ ສະແກນບາໂຄດໄວ ຄິດເງິນຫຼາຍສະກຸນ' => 'Màn hình bán hàng: quét nhanh, thanh toán nhiều loại tiền',
    'ເຄົາເຕີ້ຄິດເງິນມິນິມາດຄົບຊຸດ: ເຄື່ອງຍິງບາໂຄດ, ປິ້ນເຕີ ແລະ ລິ້ນຊັກເກັບເງິນ' => 'Quầy thu ngân trọn bộ: máy quét mã vạch, máy in và két tiền',
    'ເຄື່ອງ POS Dual Screen Touchscreen ໜ້າຈໍໃຫຍ່ ສຳຜັດໄວ' => 'Máy POS cảm ứng hai màn hình, màn hình lớn, nhạy',
    'ລະບົບຄິດເງິນຄົບຊຸດ ແລະ ພິມໃບບິນພາສາລາວ' => 'Thanh toán trọn bộ, in hóa đơn tiếng Lào',
    'ສະແກນບາໂຄດໄວ ບໍ່ຕ້ອງຈື່ລາຄາສິນຄ້າ' => 'Quét mã nhanh, không cần nhớ giá',
    'ຍິງບາໂຄດປຶບ ຊື່ສິນຄ້າ, ຮູບພາບ ແລະ ລາຄາຈະຂຶ້ນທັນທີ ຄິດເງິນໄດ້ວ່ອງໄວ ບໍ່ຜິດພາດ ແມ້ມີສິນຄ້າຫຼາຍພັນລາຍການ.' => 'Quét là hiện ngay tên, hình và giá — thanh toán nhanh, chính xác dù có hàng nghìn mặt hàng.',
    'ຄຸ້ມຄອງສະຕັອກ Real-time ປ້ອງກັນສິນຄ້າຫາຍ 100%' => 'Quản lý tồn kho thời gian thực, chống thất thoát hàng',
    'ຕັດສະຕັອກທຸກຄັ້ງທີ່ມີການຂາຍ ຮູ້ທັນທີວ່າສິນຄ້າໃດເຫຼືອເທົ່າໃດ, ແຈ້ງເຕືອນສິນຄ້າໃກ້ໝົດສະຕັອກເພື່ອສັ່ງຊື້ເພີ່ມທັນເວລາ.' => 'Trừ kho mỗi lần bán, biết ngay còn bao nhiêu, cảnh báo sắp hết để nhập kịp thời.',
    'ຮອງຮັບຫຼາຍສະກຸນເງິນ (LAK, THB, USD, CNY)' => 'Nhiều loại tiền (LAK, THB, USD, CNY)',
    'ຄິດເງິນ ແລະ ທອນເງິນໄດ້ທຸກສະກຸນເງິນຕາມອັດຕາແລກປ່ຽນປະຈຳວັນ ສະດວກສະບາຍສຳລັບລູກຄ້າທັງຄົນລາວ ແລະ ຊາວຕ່າງຊາດ.' => 'Thu và thối tiền mọi loại tiền theo tỷ giá hằng ngày, tiện cho khách Lào và nước ngoài.',
    'ລາຍງານຍອດຂາຍ, ກຳໄລ ແລະ ສິນຄ້າຂາຍດີ' => 'Báo cáo doanh số, lợi nhuận và hàng bán chạy',
    'ວິເຄາະໄດ້ວ່າສິນຄ້າໃດສ້າງກຳໄລສູງສຸດ, ສິນຄ້າໃດຄ້າງສະຕັອກຂາຍຊ້າ ຊ່ວຍໃຫ້ເຈົ້າຂອງຮ້ານຕັດສິນໃຈສັ່ງສິນຄ້າໄດ້ຢ່າງແມ່ນຍຳ.' => 'Biết sản phẩm nào lãi nhất, sản phẩm nào bán chậm, giúp nhập hàng chính xác.',
    'ຈັດການກະພະນັກງານ ແລະ ລັອກການທຸຈະລິດ' => 'Quản lý ca nhân viên và chống gian lận',
    'ແບ່ງກະການຂາຍ (Shift), ນັບເງິນສົດໃນລິ້ນຊັກກົງກັບຍອດຂາຍ, ລັອກສິດການແກ້ໄຂລາຄາ ແລະ ການຍົກເລີກບິນ ປ້ອງກັນເງິນຕົກເຮ່ຍ.' => 'Chia ca, đối chiếu tiền mặt với doanh số, khóa quyền sửa giá và hủy hóa đơn để chống thất thoát.',
    'ຮອງຮັບສິນຄ້າຫຼາຍກວ່າ 50,000+ ລາຍການ ພ້ອມຮອງຮັບບາໂຄດສິນຄ້າທົ່ວໄປ' => 'Hỗ trợ hơn 50.000 mặt hàng và mã vạch tiêu chuẩn',
    'ລະບົບພິມບາໂຄດສິນຄ້າສຳລັບສິນຄ້າທີ່ບໍ່ມີບາໂຄດມາຈາກໂຮງງານ' => 'In mã vạch cho hàng không có mã từ nhà sản xuất',
    'ຮອງຮັບການຂາຍຍົກແພັກ, ຂາຍຍົກລັງ ແລະ ຂາຍຍ່ອຍ (ຕັດສະຕັອກອັດຕະໂນມັດ)' => 'Bán theo lốc, theo thùng hoặc lẻ (tự trừ kho)',
    'ລະບົບໂປຣໂມຊັ່ນ: ຊື້ 1 ແຖມ 1, ສ່ວນຫຼຸດຕາມຊ່ວງເວລາ, ສະສົມຄະແນນສະມາຊິກ' => 'Khuyến mãi: mua 1 tặng 1, giảm giá theo khung giờ, tích điểm',
    'ເຊື່ອມຕໍ່ລິ້ນຊັກເກັບເງິນ, ເຄື່ອງຍິງບາໂຄດ, ຈໍສະແດງລາຄາລູກຄ້າ ແລະ ປິ້ນເຕີບິນ' => 'Kết nối két tiền, máy quét mã vạch, màn hình khách và máy in hóa đơn',
    'ຕິດຕາມຍອດຂາຍຜ່ານ Dashboard ໃນມືຖືໄດ້ທຸກທີ່ ຕະຫຼອດ 24 ຊົ່ວໂມງ' => 'Theo dõi doanh số trên dashboard điện thoại mọi lúc mọi nơi',
    'ລະບົບ POS ຮ້ານຂາຍຢາ ຈັດການລາຍການຢາ, ສະຕັອກ, ວັນໝົດອາຍຸ ແລະ ລາຍງານກຳໄລ' => 'POS nhà thuốc: quản lý thuốc, kho, hạn dùng và báo cáo lợi nhuận',
    'ລະບົບ POS ຮ້ານຂາຍຢາ ອອກແບບມາສະເພາະສຳລັບຮ້ານຂາຍຢາ ແລະ ຄລີນິກ: ຄຸ້ມຄອງວັນໝົດອາຍຸ (Exp Date), ຄົ້ນຫາຢາຕາມຊື່ການຄ້າ ແລະ ຊື່ສາມັນ, ຕັດສະຕັອກຫຼາຍໜ່ວຍ (ເມັດ/ແຜງ/ກ່ອງ), ພິມສະຫຼາກຢາພາສາລາວ, ແລະ ລາຍງານກຳໄລ-ຂາດທຶນ.' => 'POS dành cho nhà thuốc và phòng khám: quản lý hạn dùng, tìm theo tên thương mại hoặc tên gốc, kho nhiều đơn vị (viên/vỉ/hộp), nhãn thuốc tiếng Lào và báo cáo lãi lỗ.',
    'ໜ້າຈໍຂາຍຢາ ສະແດງສະຕັອກ, ວັນໝົດອາຍຸ ແລະ ໝວດໝູ່ຢາຊັດເຈນ' => 'Màn hình bán thuốc hiển thị rõ tồn kho, hạn dùng và danh mục',
    'ເຄື່ອງ POS Touchscreen ໜ້າຈໍໃຫຍ່ ສຳຜັດໄວ ສະອາດ ຖືກຫຼັກອະນາໄມ' => 'Máy POS cảm ứng lớn, nhạy, dễ vệ sinh',
    'ໂປຣແກຣມ POS ທັນສະໄໝ ຄຸ້ມຄອງສະຕັອກຢາ ແລະ ວັນໝົດອາຍຸ' => 'Phần mềm POS hiện đại quản lý kho thuốc và hạn dùng',
    'ອຸປະກອນຄົບຊຸດ ພ້ອມເຄື່ອງພິມສະຫຼາກຢາ ແລະ ໃບບິນ' => 'Thiết bị trọn bộ kèm máy in nhãn thuốc và hóa đơn',
    'ຄຸ້ມຄອງວັນໝົດອາຍຸ (Exp Date) & ລຸ້ນຜະລິດ (Lot)' => 'Quản lý hạn dùng và số lô',
    'ແຈ້ງເຕືອນຢາໃກ້ໝົດອາຍຸລ່ວງໜ້າ (1, 3, 6 ເດືອນ) ປ້ອງກັນການຈ່າຍຢາໝົດອາຍຸໃຫ້ຄົນໄຂ້ ແລະ ຊ່ວຍວາງແຜນລະບາຍຢາໄດ້ທັນເວລາ.' => 'Cảnh báo thuốc sắp hết hạn (1, 3, 6 tháng), tránh bán thuốc hết hạn và kịp xả hàng.',
    'ຄົ້ນຫາຢາໄດ້ໄວ ທັງຊື່ການຄ້າ ແລະ ຊື່ສາມັນ' => 'Tìm thuốc nhanh theo tên thương mại hoặc tên gốc',
    'ຊອກຫາຢາໄດ້ງ່າຍດາຍຕາມຊື່ການຄ້າ, ຊື່ສາມັນທາງຢາ (Generic Name) ຫຼື ສັບພະຄຸນ ຊ່ວຍໃຫ້ເພດສັຊກອນຈ່າຍຢາໄດ້ຖືກຕ້ອງ ແລະ ວ່ອງໄວ.' => 'Tìm theo tên thương mại, tên gốc hoặc công dụng, giúp dược sĩ bán thuốc chính xác và nhanh.',
    'ຕັດສະຕັອກຫຼາຍໜ່ວຍນັບ (ເມັດ / ແຜງ / ກ່ອງ)' => 'Trừ kho nhiều đơn vị (viên / vỉ / hộp)',
    'ຂາຍຢາເປັນເມັດ, ເປັນແຜງ, ຫຼື ເປັນກ່ອງໃຫຍ່ ລະບົບຄຳນວນແລະຕັດສະຕັອກອັດຕະໂນມັດຢ່າງຖືກຕ້ອງ ບໍ່ມີບັນຫາສະຕັອກຜິດພາດ.' => 'Bán theo viên, vỉ hoặc hộp, hệ thống tự tính và trừ kho chính xác.',
    'ພິມສະຫຼາກຢາ ແລະ ວິທີໃຊ້ຢາພາສາລາວ' => 'In nhãn thuốc và hướng dẫn dùng tiếng Lào',
    'ອອກສະຫຼາກວິທີໃຊ້ຢາ (ກິນກ່ອນ/ຫຼັງອາຫານ, ເຊົ້າ-ສວາຍ-ແລງ-ກ່ອນນອນ) ຕິດຊອງຢາໄດ້ທັນທີ ເພີ່ມຄວາມໜ້າເຊື່ອຖື ແລະ ຄວາມປອດໄພ.' => 'In nhãn cách dùng (trước/sau ăn, sáng-trưa-tối-trước khi ngủ) dán ngay lên túi thuốc, chuyên nghiệp và an toàn hơn.',
    'ບັນທຶກປະຫວັດຄົນໄຂ້ ແລະ ລາຍງານກຳໄລ-ຂາດທຶນ' => 'Lịch sử bệnh nhân và báo cáo lãi lỗ',
    'ບັນທຶກປະຫວັດການແພ້ຢາ ແລະ ປະຫວັດການຊື້ຂອງຄົນໄຂ້ ພ້ອມສະຫຼຸບລາຍຮັບ, ຕົ້ນທຶນ ແລະ ກຳໄລສຸດທິຢ່າງລະອຽດ.' => 'Ghi lại tiền sử dị ứng và lịch sử mua, kèm tổng hợp doanh thu, chi phí và lợi nhuận.',
    'ລະບົບແຈ້ງເຕືອນຢາໃກ້ໝົດອາຍຸ ແລະ ຢາໃກ້ໝົດສະຕັອກອັດຕະໂນມັດ' => 'Tự động cảnh báo thuốc sắp hết hạn và sắp hết hàng',
    'ຮອງຮັບການຂາຍຢາແຍກໜ່ວຍ: ເມັດ, ແຜງ, ຂວດ, ຫຼອດ, ກ່ອງ' => 'Bán theo đơn vị: viên, vỉ, chai, tuýp, hộp',
    'ບັນທຶກເລກທະບຽນຢາ, ລຸ້ນຜະລິດ (Lot Number) ແລະ ຜູ້ສະໜອງຢາ' => 'Ghi số đăng ký thuốc, số lô và nhà cung cấp',
    'ພິມສະຫຼາກຢາພາສາລາວຕິດຊອງຢາ ພ້ອມຊື່ຄົນໄຂ້ ແລະ ຄຳເຕືອນການໃຊ້' => 'In nhãn thuốc tiếng Lào kèm tên bệnh nhân và cảnh báo',
    'ຮອງຮັບການສະແກນບາໂຄດຢາ ແລະ ຄົ້ນຫາດ້ວຍຄີເວີດສັບພະຄຸນ' => 'Quét mã vạch thuốc và tìm theo từ khóa công dụng',
    'ລາຍງານການຂາຍຢາຄວບຄຸມພິເສດ ແລະ ສະຫຼຸບຍອດຂາຍປະຈຳວັນ' => 'Báo cáo thuốc kiểm soát đặc biệt và tổng hợp doanh số ngày',
    'ລະບົບຂາຍໜ້າຮ້ານຄົບວົງຈອນ ສຳລັບຮ້ານຂາຍຍ່ອຍ, ໂຊຫ່ວຍ, ແລະ ຮ້ານຄ້າທົ່ວໄປ' => 'Hệ thống bán hàng trọn gói cho cửa hàng bán lẻ, tạp hóa và cửa hàng chung',
    'ລະບົບ POS ຮ້ານຂາຍຍ່ອຍ ຕອບໂຈດທຸລະກິດການຄ້າຂາຍທຸກຂະໜາດ: ຄິດເງິນໄວ, ຍິງບາໂຄດແມ່ນຍຳ, ອອກໃບບິນງາມ, ຕັດສະຕັອກ Real-time, ຈັດການລູກຄ້າປະຈຳ, ແລະ ເບິ່ງຍອດຂາຍຜ່ານມືຖືໄດ້ທຸກບ່ອນ.' => 'POS bán lẻ cho mọi quy mô: thanh toán nhanh, quét chính xác, hóa đơn đẹp, tồn kho thời gian thực, quản lý khách quen và xem doanh số trên điện thoại.',
    'ໜ້າຈໍຂາຍໜ້າຮ້ານຂາຍຍ່ອຍ ຄົບວົງຈອນ ໃຊ້ງານງ່າຍ' => 'Màn hình bán lẻ đầy đủ, dễ dùng',
    'ເຄົາເຕີ້ຄິດເງິນຮ້ານຂາຍຍ່ອຍ ພ້ອມເຄື່ອງຍິງບາໂຄດ ແລະ ລິ້ນຊັກເກັບເງິນ' => 'Quầy thu ngân bán lẻ kèm máy quét mã vạch và két tiền',
    'ຄິດເງິນໄວ ຫຼຸດຄວາມຜິດພາດໃນການຂາຍ 100%' => 'Thanh toán nhanh, giảm sai sót khi bán',
    'ຍິງບາໂຄດ ຄິດເງິນ ແລະ ທອນເງິນຢ່າງຖືກຕ້ອງ ບໍ່ຕ້ອງເສຍເວລາກົດເຄື່ອງຄິດເລກ ຫຼຸດການຕົກຫຼົ່ນຂອງຍອດຂາຍ.' => 'Quét, tính tiền và thối tiền chính xác, không cần máy tính, giảm thất thoát doanh số.',
    'ຄຸ້ມຄອງສາງສິນຄ້າ & ຕັດສະຕັອກອັດຕະໂນມັດ' => 'Quản lý kho và tự động trừ tồn',
    'ຮູ້ຍອດສິນຄ້າເຫຼືອໃນຮ້ານທັນທີ ບໍ່ຕ້ອງນັ່ງນັບສະຕັອກທຸກມື້, ແຈ້ງເຕືອນສິນຄ້າໃກ້ໝົດສະຕັອກ ປ້ອງກັນສິນຄ້າຂາດຮ້ານ.' => 'Biết ngay hàng còn lại, không cần đếm kho mỗi ngày, cảnh báo sắp hết để không thiếu hàng.',
    'ປ້ອງກັນເງິນຕົກເຮ່ຍ ແລະ ກວດສອບຍອດຂາຍໄດ້ທຸກເວລາ' => 'Chống thất thoát và kiểm tra doanh số mọi lúc',
    'ບັນທຶກທຸກຍອດຂາຍຢ່າງລະອຽດ, ເປີດລິ້ນຊັກເກັບເງິນສະເພາະຕອນພິມບິນ, ກວດຍອດຂາຍໄດ້ຕະຫຼອດ.' => 'Ghi chi tiết mọi giao dịch, két chỉ mở khi in hóa đơn, kiểm tra doanh số bất cứ lúc nào.',
    'ຕິດຕາມຍອດຂາຍໄດ້ທຸກທີ່ຜ່ານມືຖື ຕະຫຼອດ 24 ຊົ່ວໂມງ' => 'Theo dõi doanh số mọi nơi trên điện thoại 24/7',
    'ເບິ່ງຍອດຂາຍປະຈຳວັນ, ກຳໄລສຸດທິ ແລະ ລາຍການສິນຄ້າຂາຍດີຜ່ານໂທລະສັບມືຖື ຢູ່ໃສກໍສາມາດບໍລິຫານຮ້ານໄດ້.' => 'Xem doanh số ngày, lợi nhuận và hàng bán chạy trên điện thoại, quản lý cửa hàng ở bất cứ đâu.',
    'ລະບົບສະມາຊິກ & ສະສົມແຕ້ມ ດຶງດູດລູກຄ້າກັບມາຊື້ຊ້ຳ' => 'Thành viên và tích điểm, thu hút khách quay lại',
    'ບັນທຶກເບີໂທລູກຄ້າ, ໃຫ້ຄະແນນສະສົມ, ມອບສ່ວນຫຼຸດພິເສດສຳລັບລູກຄ້າປະຈຳ ເພີ່ມຍອດຂາຍໃຫ້ຮ້ານຢ່າງຍືນຍົງ.' => 'Lưu số điện thoại khách, tặng điểm và giảm giá cho khách quen, tăng doanh số bền vững.',
    'ຮອງຮັບການສະແກນບາໂຄດທັງ 1D ແລະ 2D ວ່ອງໄວ' => 'Quét nhanh mã vạch 1D và 2D',
    'ຮອງຮັບຫຼາຍສະກຸນເງິນ: ກີບ (LAK), ບາດ (THB), ໂດລາ (USD), ຢວນ (CNY)' => 'Nhiều loại tiền: kíp (LAK), baht (THB), đô la (USD), nhân dân tệ (CNY)',
    'ພິມໃບບິນຮັບເງິນພາສາລາວ ພ້ອມໂລໂກ້ຮ້ານຄ້າ' => 'In biên lai tiếng Lào kèm logo cửa hàng',
    'ລະບົບສະມາຊິກ, ສະສົມແຕ້ມ, ແລະ ສ່ວນຫຼຸດໂປຣໂມຊັ່ນ' => 'Thành viên, tích điểm và giảm giá khuyến mãi',
    'ຈັດການຫຼາຍສາຂາ ແລະ ໂອນຍ້າຍສິນຄ້າລະຫວ່າງສາຂາ' => 'Quản lý nhiều chi nhánh và chuyển hàng giữa các chi nhánh',
    'ລາຍງານສະຫຼຸບຍອດຂາຍ, ຍອດກຳໄລ, ແລະ ຍອດສິນຄ້າຄົງເຫຼືອແບບ Real-time' => 'Báo cáo doanh số, lợi nhuận và tồn kho theo thời gian thực',
    'ລະບົບ POS ຮ້ານອາຫານ ຄົບວົງຈອນ: ຈັດການໂຕະ, ສົ່ງອໍເດີເຂົ້າຄົວ, ແຍກບິນ ແລະ ຕັດສະຕັອກ' => 'POS nhà hàng trọn gói: quản lý bàn, gửi order vào bếp, tách hóa đơn và kho',
    'ລະບົບ POS ຮ້ານອາຫານ ອອກແບບມາເພື່ອຮອງຮັບຮ້ານອາຫານຂະໜາດນ້ອຍເຖິງໃຫຍ່: ແຜນຜັງໂຕະສະເໝືອນຈິງ, ສັ່ງອາຫານຜ່ານແທັບເລັດ/ມືຖື, ສົ່ງອໍເດີເຂົ້າຄົວອັດຕະໂນມັດ, ແຍກບິນ/ລວມບິນ, ຕັດສະຕັອກວັດຖຸດິບ, ແລະ ລາຍງານຍອດຂາຍ Real-time.' => 'POS nhà hàng cho quán nhỏ đến lớn: sơ đồ bàn trực quan, gọi món trên máy tính bảng/điện thoại, tự gửi order vào bếp, tách/gộp hóa đơn và báo cáo doanh số thời gian thực.',
    'ໜ້າຈໍລະບົບ POS ຮ້ານອາຫານ ສຳຜັດງ່າຍ ເມນູພາບງາມ ຈັດການໂຕະ' => 'Màn hình POS nhà hàng cảm ứng, menu hình ảnh, quản lý bàn',
    'ເຄື່ອງ POS Dual Screen Touchscreen ຄົບຊຸດພ້ອມລິ້ນຊັກ ແລະ ປິ້ນເຕີບິນ' => 'Máy POS cảm ứng hai màn hình trọn bộ kèm két và máy in',
    'ລະບົບຄິດເງິນ ແລະ ພິມໃບສັ່ງອາຫານເຂົ້າຄົວ (Kitchen Printer)' => 'Thanh toán và in phiếu bếp',
    'ບັນຍາກາດການໃຊ້ງານໃນຮ້ານອາຫານ ຈັດການໂຕະ ແລະ ອໍເດີ' => 'Sử dụng tại nhà hàng: quản lý bàn và order',
    'ສົ່ງອໍເດີເຂົ້າຄົວທັນທີ ຫຼຸດເວລາລໍຖ້າອາຫານ 50%' => 'Order vào bếp ngay, giảm một nửa thời gian chờ',
    'ເມື່ອກົດສັ່ງ, ລາຍການອາຫານຈະຖືກພິມອອກທີ່ຄົວ ແລະ ບາຣ໌ນ້ຳທັນທີ ພໍ່ຄົວປຸງອາຫານໄດ້ຕໍ່ເນື່ອງ ບໍ່ມີອໍເດີຕົກຫຼົ່ນ.' => 'Vừa gọi món là phiếu in ngay ở bếp và quầy nước, đầu bếp làm liên tục, không sót order.',
    'ຈັດການແຜນຜັງໂຕະ, ຍ້າຍໂຕະ ແລະ ລວມໂຕະງ່າຍດາຍ' => 'Dễ dàng quản lý sơ đồ bàn, chuyển và gộp bàn',
    'ເບິ່ງສະຖານະໂຕະວ່າງ/ບໍ່ວ່າງໄດ້ທັນທີ, ຮອງຮັບການຍ້າຍໂຕະ, ລວມໂຕະ, ແລະ ແຍກບິນຕາມກຸ່ມລູກຄ້າ.' => 'Xem ngay bàn trống/có khách, hỗ trợ chuyển bàn, gộp bàn và tách hóa đơn theo nhóm.',
    'ພັກບິນໄວ້ ສັ່ງເພີ່ມໄດ້ຈົນກວ່າຈະຊຳລະ' => 'Giữ hóa đơn, gọi thêm đến khi thanh toán',
    'ບິນຂອງແຕ່ລະໂຕະຖືກບັນທຶກໄວ້ໃນລະບົບ ລູກຄ້າສັ່ງເພີ່ມເທື່ອໃດກໍ່ໄດ້ ບໍ່ຫາຍ ເຖິງວ່າຈະປິດເຄື່ອງ.' => 'Hóa đơn từng bàn được lưu trong hệ thống, khách gọi thêm lúc nào cũng được, không mất dù tắt máy.',
    'ຕິດຕາມຍອດຂາຍ ແລະ ໂຕະທີ່ກຳລັງກິນຜ່ານມືຖື' => 'Theo dõi doanh số và bàn đang dùng trên điện thoại',
    'ເຈົ້າຂອງຮ້ານກວດເບິ່ງຍອດຂາຍ, ຍອດບິນ, ແລະ ລາຍການອາຫານຂາຍດີຜ່ານໂທລະສັບມືຖືໄດ້ຕະຫຼອດ 24 ຊົ່ວໂມງ.' => 'Chủ quán xem doanh số, hóa đơn và món bán chạy trên điện thoại 24 giờ.',
    'ປ້ອງກັນເງິນຕົກເຮ່ຍ & ຄຸ້ມຄອງພະນັກງານເສີບ' => 'Chống thất thoát và quản lý phục vụ',
    'ແຍກສິດພະນັກງານ (ພະນັກງານເສີບ, ແຄັດເຊຍ, ຜູ້ຈັດການ), ລັອກສິດການຍົກເລີກອາຫານ, ແລະ ກວດສອບຍອດເງິນໂປ່ງໃສ.' => 'Phân quyền nhân viên (phục vụ, thu ngân, quản lý), khóa quyền hủy món, kiểm tra tiền minh bạch.',
    'ແຜນຜັງໂຕະສະເໝືອນຈິງ ແບ່ງໂຊນ Indoor, Outdoor, VIP' => 'Sơ đồ bàn trực quan, chia khu trong nhà, ngoài trời, VIP',
    'ຮອງຮັບການສັ່ງອາຫານຜ່ານແທັບເລັດ ຫຼື ມືຖືຂອງພະນັກງານເສີບ' => 'Phục vụ gọi món bằng máy tính bảng hoặc điện thoại',
    'ພິມໃບສັ່ງແຍກຄົວ (ຄົວຕົ້ມ, ຄົວປີ້ງ, ບາຣ໌ນ້ຳ) ອັດຕະໂນມັດ' => 'Tự in phiếu theo từng bếp (nấu, nướng, quầy nước)',
    'ຮອງຮັບການແຍກບິນ, ລວມບິນ, ແລະ ໃສ່ສ່ວນຫຼຸດ (VIP, ວັນເກີດ)' => 'Tách, gộp hóa đơn và áp giảm giá (VIP, sinh nhật)',
    'ສະຫຼຸບຍອດຂາຍປະຈຳວັນ, ປິດກະການຂາຍ, ແລະ ລາຍງານຍອດນິຍົມ' => 'Tổng hợp doanh số ngày, chốt ca và báo cáo món phổ biến',
    '%s ຄຸນນະພາບສູງ ພ້ອມຕິດຕັ້ງ ແລະ ເຊື່ອມຕໍ່ລະບົບ POS ທັນທີ' => '%s chất lượng cao, lắp đặt và kết nối POS ngay',
    '%s ອຸປະກອນມາດຕະຖານສຳລັບຮ້ານຄ້າ ແລະ ທຸລະກິດທຸກຂະໜາດ ທົນທານ ໃຊ້ງານງ່າຍ ຮອງຮັບການເຊື່ອມຕໍ່ກັບລະບົບຂາຍໜ້າຮ້ານ POS ພ້ອມບໍລິການຕິດຕັ້ງ ແລະ ຮັບປະກັນໂດຍທີມງານມືອາຊີບ.' => '%s — thiết bị tiêu chuẩn cho cửa hàng và doanh nghiệp mọi quy mô: bền, dễ dùng, tương thích POS, có lắp đặt và bảo hành bởi đội ngũ chuyên nghiệp.',
    'ອຸປະກອນ POS ຄົບຊຸດ ພ້ອມໃຊ້ງານ' => 'Thiết bị POS trọn bộ, sẵn sàng sử dụng',
    'ເຮັດວຽກວ່ອງໄວ ແມ່ນຍຳ ທົນທານຕໍ່ການໃຊ້ງານໜັກ' => 'Nhanh, chính xác, bền bỉ khi dùng nhiều',
    'ອຸປະກອນຄຸນນະພາບມາດຕະຖານ ຮອງຮັບການເຮັດວຽກຕໍ່ເນື່ອງໜ້າຮ້ານທັງວັນ.' => 'Thiết bị chất lượng, hoạt động liên tục cả ngày tại quầy.',
    'ເຊື່ອມຕໍ່ລະບົບ POS ໄດ້ທັນທີ (Plug & Play)' => 'Kết nối POS ngay (Plug & Play)',
    'ຮອງຮັບການເຊື່ອມຕໍ່ USB / LAN / Bluetooth ເຂົ້າກັບຄອມພິວເຕີ ແລະ ເຄື່ອງ POS.' => 'Kết nối USB / LAN / Bluetooth với máy tính và máy POS.',
    'ຕິດຕັ້ງຟຣີ ພ້ອມສອນການໃຊ້ງານ ແລະ ຮັບປະກັນ' => 'Lắp đặt miễn phí, hướng dẫn và bảo hành',
    'ທີມງານຕັ້ງຄ່າ ທົດສອບລະບົບໃຫ້ພ້ອມໃຊ້ງານ ແລະ ດູແລຫຼັງການຂາຍຕະຫຼອດອາຍຸການໃຊ້ງານ.' => 'Đội ngũ cài đặt, kiểm tra và hỗ trợ suốt vòng đời sản phẩm.',
    'ວັດສະດຸແຂງແຮງ ທົນທານ ອອກແບບມາສຳລັບວຽກຂາຍໜ້າຮ້ານໂດຍສະເພາະ' => 'Vật liệu chắc chắn, bền, thiết kế cho quầy bán hàng',
    'ເຊື່ອມຕໍ່ເຂົ້າກັບໂປຣແກຣມ POS ໄດ້ທຸກຮູບແບບ' => 'Tương thích mọi phần mềm POS',
    'ຮອງຮັບການພິມ/ສະແກນ ຫຼື ໃຊ້ງານຮ່ວມກັບພາສາລາວຢ່າງສົມບູນ' => 'Hỗ trợ đầy đủ tiếng Lào khi in/quét',
    'ຕິດຕັ້ງ ແລະ ຕັ້ງຄ່າໃຫ້ພ້ອມໃຊ້ງານໂດຍທີມງານ WlaoDev' => 'Được đội ngũ WlaoDev lắp đặt và cấu hình',
    'ມີບໍລິການຫຼັງການຂາຍ ແລະ ອະໄຫຼ່ຮອງຮັບຄົບຖ້ວນ' => 'Dịch vụ hậu mãi và linh kiện đầy đủ',
    'ລະບົບຂາຍໜ້າຮ້ານ POS ຄົບວົງຈອນ ຕອບໂຈດທຸລະກິດຂອງທ່ານ' => 'Hệ thống POS trọn gói phù hợp với doanh nghiệp của bạn',
    'ລະບົບ POS %s ອອກແບບມາເພື່ອຊ່ວຍໃຫ້ທຸລະກິດຂອງທ່ານດຳເນີນງານຢ່າງມີປະສິດທິພາບສູງສຸດ: ຂາຍໜ້າຮ້ານໄວ, ຕັດສະຕັອກອັດຕະໂນມັດ, ປ້ອງກັນເງິນຕົກເຮ່ຍ, ພິມໃບບິນພາສາລາວ, ແລະ ເບິ່ງຍອດຂາຍຜ່ານມືຖືໄດ້ທຸກບ່ອນ.' => 'Hệ thống POS cho %s giúp kinh doanh hiệu quả: bán nhanh, tự trừ kho, chống thất thoát, hóa đơn tiếng Lào và xem doanh số trên điện thoại mọi nơi.',
    'ເຄື່ອງ POS Dual Screen Touchscreen ແລະ ອຸປະກອນຄົບຊຸດ' => 'Máy POS cảm ứng hai màn hình và thiết bị trọn bộ',
    'ໂປຣແກຣມ POS ທັນສະໄໝ ຮອງຮັບ Smart Touch' => 'Phần mềm POS hiện đại hỗ trợ cảm ứng',
    'ລະບົບຄິດເງິນ ແລະ ຊຳລະສະດວກທຸກຮູບແບບ' => 'Thanh toán thuận tiện mọi hình thức',
    'ບໍລິການລູກຄ້າໄວຂຶ້ນ ແລະ ຫຼຸດຄວາມຜິດພາດ 100%' => 'Phục vụ khách nhanh hơn, ít sai sót hơn',
    'ລະບົບຊ່ວຍໃຫ້ຄິດເງິນ ອອກໃບບິນ ແລະ ຕັດສະຕັອກໄດ້ໄວ ຫຼຸດເວລາລໍຖ້າຂອງລູກຄ້າ ແລະ ບໍ່ມີຍອດຂາຍຕົກຫຼົ່ນ.' => 'Thanh toán, in hóa đơn và trừ kho nhanh, khách chờ ít hơn, không sót doanh số.',
    'ຕັດສະຕັອກ Real-time ຮູ້ຍອດສິນຄ້າເຫຼືອທັນທີ' => 'Trừ kho thời gian thực, biết ngay hàng còn lại',
    'ຕັດສະຕັອກທຸກຄັ້ງທີ່ຂາຍ ແຈ້ງເຕືອນສິນຄ້າໃກ້ໝົດ ປ້ອງກັນສິນຄ້າຂາດຮ້ານ ແລະ ສິນຄ້າສູນຫາຍ.' => 'Trừ kho mỗi lần bán, cảnh báo sắp hết, chống thiếu hàng và thất thoát.',
    'ບັນທຶກທຸກຍອດຂາຍຢ່າງລະອຽດ, ແຍກກະການຂາຍ, ລັອກສິດການຍົກເລີກບິນ ປ້ອງກັນການທຸຈະລິດ.' => 'Ghi chi tiết mọi giao dịch, chia ca, khóa quyền hủy hóa đơn để chống gian lận.',
    'ຕິດຕາມຍອດຂາຍ ແລະ ກຳໄລໄດ້ທຸກທີ່ຜ່ານມືຖື' => 'Theo dõi doanh số và lợi nhuận mọi nơi trên điện thoại',
    'ເຈົ້າຂອງທຸລະກິດເບິ່ງຍອດຂາຍ, ຕົ້ນທຶນ ແລະ ກຳໄລສຸດທິຜ່ານມືຖືໄດ້ຕະຫຼອດ 24 ຊົ່ວໂມງ ບໍ່ຈຳເປັນຕ້ອງຢູ່ຮ້ານ.' => 'Chủ doanh nghiệp xem doanh số, chi phí và lợi nhuận trên điện thoại 24 giờ mà không cần ở cửa hàng.',
    'ໜ້າຈໍຂາຍໜ້າຮ້ານສຳຜັດງ່າຍ ເມນູພາບງາມ ໃຊ້ງານເປັນພາຍໃນ 5 ນາທີ' => 'Màn hình bán hàng cảm ứng, menu hình ảnh, dùng được trong 5 phút',
    'ຮອງຮັບການພິມໃບບິນພາສາລາວ ພ້ອມໂລໂກ້ຮ້ານຄ້າ' => 'Hỗ trợ in hóa đơn tiếng Lào kèm logo',
    'ເຊື່ອມຕໍ່ອຸປະກອນ: ປິ້ນເຕີບິນ, ເຄື່ອງຍິງບາໂຄດ, ລິ້ນຊັກເກັບເງິນ' => 'Kết nối thiết bị: máy in hóa đơn, máy quét mã vạch, két tiền',
    'ລາຍງານຍອດຂາຍ ແລະ ກຳໄລ Real-time ຜ່ານມືຖື' => 'Báo cáo doanh số và lợi nhuận thời gian thực trên điện thoại',
    'ເຮັດວຽກໄດ້ທັງ Offline (ເນັດຫຼຸດຍັງຂາຍໄດ້) ແລະ Online' => 'Hoạt động ngoại tuyến (mất mạng vẫn bán) và trực tuyến',
    'ລູກຄ້າຕໍ່ຄິວຍາວ ຮັບອໍເດີບໍ່ທັນ' => 'Khách xếp hàng dài, nhận order không kịp',
    'ສັ່ງນ້ຳຜິດ ລືມອໍເດີ ຕ້ອງຮ້ອງບອກກັນ' => 'Pha sai, quên order, phải gọi to cho nhau',
    'ຢາກຈັດໂປຣ ແຕ່ຄິດສ່ວນຫຼຸດດ້ວຍມື ຜິດ ແລະ ຊ້າ' => 'Muốn khuyến mãi nhưng tính giảm giá bằng tay vừa chậm vừa sai',
    'ຕ້ອງຢູ່ຮ້ານຕະຫຼອດ ຈຶ່ງຮູ້ຍອດຂາຍ' => 'Phải ở cửa hàng mới biết doanh số',
    'ເງິນໃນລິ້ນຊັກບໍ່ກົງກັບຍອດຂາຍ' => 'Tiền trong két không khớp doanh số',
    'ສິນຄ້າຫຼາຍ ຈື່ລາຄາບໍ່ໄດ້ ຄິດເງິນຊ້າ' => 'Nhiều hàng, không nhớ giá, tính tiền chậm',
    'ສິນຄ້າຫາຍ ບໍ່ຮູ້ວ່າເຫຼືອເທົ່າໃດ' => 'Hàng mất, không biết còn bao nhiêu',
    'ລູກຄ້າຈ່າຍເງິນບາດ, ໂດລາ ຄິດແລກປ່ຽນຍາກ' => 'Khách trả baht, đô la, quy đổi khó',
    'ບໍ່ຮູ້ວ່າສິນຄ້າໃດຂາຍດີ ກຳໄລເທົ່າໃດ' => 'Không biết hàng nào bán chạy, lãi bao nhiêu',
    'ປ່ຽນກະແລ້ວເງິນຂາດ ບໍ່ຮູ້ວ່າຂາດຍ້ອນໃຜ' => 'Đổi ca xong thiếu tiền, không biết do ai',
    'ຢາໝົດອາຍຸຄ້າງຮ້ານ ບໍ່ຮູ້ຕົວ' => 'Thuốc hết hạn còn trong cửa hàng mà không biết',
    'ຊອກຢາຊ້າ ຈື່ຊື່ຢາບໍ່ໄດ້ໝົດ' => 'Tìm thuốc chậm, không nhớ hết tên',
    'ຂາຍເປັນເມັດ ເປັນແຜງ ນັບສະຕັອກສັບສົນ' => 'Bán theo viên, theo vỉ, đếm kho rối',
    'ຂຽນວິທີໃຊ້ຢາດ້ວຍມື ເສຍເວລາ ອ່ານຍາກ' => 'Viết tay cách dùng thuốc mất thời gian, khó đọc',
    'ບໍ່ມີປະຫວັດລູກຄ້າ ບໍ່ຮູ້ກຳໄລແທ້' => 'Không có lịch sử khách, không biết lãi thật',
    'ຄິດເງິນດ້ວຍມື ຊ້າ ແລະ ຜິດພາດ' => 'Tính tiền bằng tay chậm và sai',
    'ສິນຄ້າໃນສາງເຫຼືອເທົ່າໃດ ບໍ່ຮູ້' => 'Không biết trong kho còn bao nhiêu',
    'ເງິນຕົກເຮ່ຍ ກວດສອບບໍ່ໄດ້' => 'Thất thoát tiền mà không kiểm tra được',
    'ຢູ່ນອກຮ້ານ ບໍ່ຮູ້ວ່າຂາຍໄດ້ເທົ່າໃດ' => 'Không ở cửa hàng thì không biết bán được bao nhiêu',
    'ລູກຄ້າຊື້ເທື່ອດຽວ ບໍ່ກັບມາອີກ' => 'Khách mua một lần rồi không quay lại',
    'ອໍເດີຕົກຫຼົ່ນ ລູກຄ້າລໍຖ້າອາຫານດົນ' => 'Sót order, khách chờ món lâu',
    'ໂຕະເຕັມ ສັບສົນ ບໍ່ຮູ້ໂຕະໃດວ່າງ' => 'Đông khách, rối, không biết bàn nào trống',
    'ລູກຄ້າສັ່ງເພີ່ມ ຈື່ບໍ່ໄດ້ວ່າໂຕະໃດສັ່ງຫຍັງ' => 'Khách gọi thêm, không nhớ bàn nào gọi gì',
    'ພະນັກງານຍົກເລີກອາຫານ ເງິນບໍ່ກົງ' => 'Nhân viên hủy món, tiền không khớp',
    'ລູກຄ້າລໍຖ້າດົນ ຄິດເງິນຜິດ' => 'Khách chờ lâu, tính tiền sai',
    'ສິນຄ້າໝົດ ຫຼື ຫາຍ ບໍ່ຮູ້ຕົວ' => 'Hàng hết hoặc mất mà không biết',
    'ພະນັກງານບໍ່ເກັ່ງຄອມ ຈະໃຊ້ເປັນບໍ?' => 'Nhân viên không giỏi máy tính, có dùng được không?',
    'ໃຊ້ເປັນແນ່ນອນ — ໜ້າຈໍກົດງ່າຍຄືໃຊ້ມືຖື ທີມງານສອນເຖິງຮ້ານຈົນພະນັກງານຂາຍເອງໄດ້ ສ່ວນຫຼາຍໃຊ້ເປັນພາຍໃນມື້ດຽວ.' => 'Chắc chắn được — màn hình dễ như dùng điện thoại, chúng tôi hướng dẫn tại cửa hàng đến khi nhân viên tự bán được, đa số học xong trong một ngày.',
    'ລະບົບມີບັນຫາຕອນກາງຄືນ ຫຼື ວັນພັກ ຕິດຕໍ່ໃຜ?' => 'Hệ thống gặp sự cố ban đêm hoặc ngày nghỉ thì liên hệ ai?',
    'ໂທ ຫຼື WhatsApp ຫາທີມງານໄດ້ 24 ຊົ່ວໂມງ ທຸກມື້ — ແກ້ໄຂຜ່ານອອນລາຍທັນທີ ຖ້າຈຳເປັນຈະລົງໄປເຖິງຮ້ານ.' => 'Gọi hoặc WhatsApp cho chúng tôi 24 giờ mỗi ngày — xử lý trực tuyến ngay, cần thiết sẽ đến tận cửa hàng.',
    'ຢາກເພີ່ມ ຫຼື ປ່ຽນຟັງຊັນໃຫ້ເໝາະກັບຮ້ານ ໄດ້ບໍ?' => 'Có thể thêm hoặc đổi chức năng cho phù hợp cửa hàng không?',
    'ໄດ້ — ພວກເຮົາພັດທະນາລະບົບເອງ ຈຶ່ງປັບແຕ່ງໃຫ້ຕາມຄວາມຕ້ອງການຂອງຮ້ານທ່ານໄດ້.' => 'Được — chúng tôi tự phát triển hệ thống nên tùy chỉnh theo nhu cầu cửa hàng của bạn.',
    'ຖ້າອິນເຕີເນັດຫຼຸດ ລະບົບຍັງສາມາດຂາຍ ແລະ ອອກບິນໄດ້ບໍ່?' => 'Mất mạng thì hệ thống vẫn bán và in hóa đơn được không?',
    'ສາມາດຂາຍໄດ້ປົກກະຕິ 100%! ລະບົບຖືກອອກແບບມາໃຫ້ຮອງຮັບທັງແບບ Offline ແລະ Online ເມື່ອອິນເຕີເນັດກັບມາ ລະບົບຈະ Sync ຂໍ້ມູນຂຶ້ນຄລາວອັດຕະໂນມັດ.' => 'Vẫn bán bình thường! Hệ thống hỗ trợ cả ngoại tuyến và trực tuyến, có mạng lại sẽ tự đồng bộ lên đám mây.',
    'ມີທີມງານສອນການໃຊ້ງານ ແລະ ຕິດຕັ້ງໃຫ້ບໍ່?' => 'Có đội ngũ lắp đặt và hướng dẫn không?',
    'ມີທີມງານຊ່ຽວຊານໄປຕິດຕັ້ງ ແລະ ສອນການໃຊ້ງານເຖິງສະຖານທີ່ຂອງທ່ານ (ຫຼື ຜ່ານອອນລາຍ) ພ້ອມຄູ່ມືພາສາລາວ ແລະ ວິດີໂອສອນທຸກຂັ້ນຕອນ.' => 'Có chuyên viên lắp đặt và hướng dẫn tận nơi (hoặc trực tuyến), kèm sổ tay tiếng Lào và video từng bước.',
    'ອຸປະກອນມີການຮັບປະກັນແນວໃດ?' => 'Thiết bị được bảo hành thế nào?',
    'ອຸປະກອນທຸກຊິ້ນຮັບປະກັນ 1 ປີເຕັມ. ຫາກມີບັນຫາທາງທີມງານມີເຄື່ອງສຳຮອງໃຫ້ໃຊ້ງານທັນທີ ເພື່ອບໍ່ໃຫ້ທຸລະກິດຂອງທ່ານສະດຸດ.' => 'Mọi thiết bị bảo hành 1 năm. Nếu có sự cố, chúng tôi cho mượn máy thay thế ngay để kinh doanh không gián đoạn.',
    'ສາມາດເບິ່ງຍອດຂາຍຜ່ານໂທລະສັບມືຖືໄດ້ບໍ່?' => 'Có xem doanh số trên điện thoại được không?',
    'ໄດ້ແນ່ນອນ! ທ່ານສາມາດກວດເບິ່ງຍອດຂາຍ, ຍອດບິນ, ສິນຄ້າຂາຍດີ ແລະ ກຳໄລສຸດທິຜ່ານມືຖືໄດ້ທຸກບ່ອນ ຕະຫຼອດ 24 ຊົ່ວໂມງ.' => 'Tất nhiên! Xem doanh số, hóa đơn, hàng bán chạy và lợi nhuận trên điện thoại mọi nơi, 24 giờ.',
    'ສາມາດອອກໃບສະເໜີລາຄາ ແລະ ໃບຮັບເງິນໃນນາມບໍລິສັດໄດ້ບໍ່?' => 'Có xuất báo giá và biên lai đứng tên công ty không?',
    'ໄດ້ຢ່າງແນ່ນອນ. ພວກເຮົາສາມາດອອກໃບສະເໜີລາຄາ (Quotation), ໃບຮຽກເກັບເງິນ (Invoice) ແລະ ໃບຮັບເງິນທີ່ຖືກຕ້ອງຕາມກົດໝາຍໃຫ້ອົງກອນ ແລະ ບໍລິສັດ.' => 'Chắc chắn. Chúng tôi xuất báo giá, hóa đơn và biên lai hợp lệ cho tổ chức và công ty.',
    'ທີມພັດທະນາລະບົບ POS, ເວັບໄຊ ແລະ ແອັບມືຖື ທີ່ເຂົ້າໃຈທຸລະກິດລາວ' => 'Đội ngũ phát triển POS, website và ứng dụng hiểu doanh nghiệp Lào',
    'ສະບາຍດີ ສົນໃຈປຶກສາລະບົບ' => 'Xin chào, tôi muốn tư vấn hệ thống',
    'ຊົ່ວໂມງ ດູແລຫຼັງການຂາຍ' => 'giờ hỗ trợ hậu mãi',
    'ພາສາລາວທຸກໜ້າຈໍ' => 'Tiếng Lào trên mọi màn hình',
    'ໃບບິນ, ລາຍງານ ແລະ ເມນູເປັນພາສາລາວ ຮອງຮັບ 5 ພາສາ' => 'Hóa đơn, báo cáo và menu bằng tiếng Lào, hỗ trợ 5 ngôn ngữ',
    'ໃຊ້ໄດ້ທຸກອຸປະກອນ' => 'Dùng trên mọi thiết bị',
