    '%s ພັດທະນາລະບົບ POS, ເວັບໄຊ ແລະ ແອັບມືຖື ເປັນພາສາລາວ ໃຊ້ງານງ່າຍ — ລູກຄ້າຕ້ອງການແນວໃດ ພວກເຮົາເຮັດໃຫ້ໄດ້.' => '%s phát triển POS, website và ứng dụng di động tiếng Lào dễ dùng — bạn cần gì, chúng tôi làm được.',
