    'ຖາມໄດ້ທັນທີ ບໍ່ຕ້ອງລົງທະບຽນ' => 'Hỏi ngay, không cần đăng ký',
    'ດູແລຫຼັງການຂາຍ 24 ຊົ່ວໂມງ' => 'Hỗ trợ hậu mãi 24 giờ',
