    'ບັນທຶກຂໍ້ມູນສັ່ງຊື້ສຳເລັດ' => 'Đã lưu đơn hàng',

    'ບັນທຶກຂໍ້ມູນທີ່ຢູ່ຈັດສົ່ງສຳເລັດ!' => 'Đã lưu địa chỉ giao hàng!',
    'ກະລຸນາຕິດຕໍ່ທີມງານເພື່ອສອບຖາມລາຄາພິເສດ ແລະ ຊຳລະເງິນ — ເມື່ອໂອນເງິນແລ້ວ ພະນັກງານຫຼັງບ້ານຈະຈັດຝາກເຄື່ອງໃຫ້ຕາມຂໍ້ມູນລຸ່ມນີ້ທັນທີ.' => 'Vui lòng liên hệ chúng tôi để biết giá ưu đãi và thanh toán — sau khi chuyển khoản, nhân viên sẽ gửi hàng ngay theo thông tin dưới đây.',
    'ຜູ້ຮັບສິນຄ້າ:' => 'Người nhận:',
    'ທີ່ຢູ່ຈັດສົ່ງ:' => 'Địa chỉ giao hàng:',
