    'ຍອດລວມທັງໝົດ' => 'Tổng cộng',
    'ຕິດຕາມສະຖານະອໍເດີ' => 'Theo dõi trạng thái đơn',
    'ຕິດຕໍ່ໂອນເງິນຜ່ານ WhatsApp' => 'Liên hệ chuyển khoản qua WhatsApp',
    'ເບິ່ງສິນຄ້າອື່ນຕໍ່' => 'Xem sản phẩm khác',
    'ນະໂຍບາຍການເກັບກຳ, ນຳໃຊ້ ແລະ ປົກປ້ອງຂໍ້ມູນສ່ວນຕົວ ແລະ ຂໍ້ມູນທຸລະກິດຂອງລູກຄ້າ' => 'Chính sách thu thập, sử dụng và bảo vệ dữ liệu cá nhân và kinh doanh của khách hàng',
    'ເງື່ອນໄຂການໃຫ້ບໍລິການລະບົບ POS, ອຸປະກອນ, ການຕິດຕັ້ງ ແລະ ການຮັບປະກັນຫຼັງການຂາຍ' => 'Điều khoản dịch vụ POS, thiết bị, lắp đặt và bảo hành hậu mãi',
    'ການເກັບກຳຂໍ້ມູນ' => 'Thu thập dữ liệu',
    'ພວກເຮົາໃຫ້ຄວາມສຳຄັນສູງສຸດຕໍ່ຄວາມປອດໄພຂອງຂໍ້ມູນລູກຄ້າ ແລະ ຂໍ້ມູນການຂາຍຂອງຮ້ານຄ້າ ໂດຍເກັບກຳສະເພາະຂໍ້ມູນທີ່ຈຳເປັນຕໍ່ການໃຫ້ບໍລິການ:' => 'Chúng tôi coi trọng bảo mật dữ liệu khách hàng và dữ liệu bán hàng, chỉ thu thập thông tin cần thiết để cung cấp dịch vụ:',
    'ຂໍ້ມູນການຕິດຕໍ່ ເຊັ່ນ: ຊື່-ນາມສະກຸນ, ຊື່ຮ້ານ/ບໍລິສັດ, ເບີໂທລະສັບ, WhatsApp, ອີເມວ ແລະ ທີ່ຢູ່ຈັດສົ່ງ ທີ່ລູກຄ້າແຈ້ງຜ່ານເວັບໄຊ.' => 'Thông tin liên hệ như họ tên, tên cửa hàng/công ty, điện thoại, WhatsApp, email và địa chỉ giao hàng bạn cung cấp qua website.',
    'ຂໍ້ມູນລາຍລະອຽດການສັ່ງຊື້ອຸປະກອນ POS, ແພັກເກດລະບົບ ແລະ ປະຫວັດການຮັບບໍລິການຫຼັງການຂາຍ.' => 'Chi tiết đơn hàng thiết bị POS, gói hệ thống và lịch sử dịch vụ hậu mãi.',
    'ວັດຖຸປະສົງການໃຊ້ຂໍ້ມູນ' => 'Mục đích sử dụng dữ liệu',
    'ໃຊ້ເພື່ອຕິດຕໍ່ກັບ, ຢືນຢັນຄຳສັ່ງຊື້, ຈັດສົ່ງອຸປະກອນ ແລະ ນັດໝາຍຕິດຕັ້ງລະບົບ.' => 'Để liên hệ, xác nhận đơn hàng, giao thiết bị và hẹn lắp đặt.',
    'ໃຊ້ເພື່ອການດູແລຫຼັງການຂາຍ, ການອັບເດດລະບົບ ແລະ ການແກ້ໄຂບັນຫາດ້ານເຕັກນິກໃຫ້ແກ່ລູກຄ້າ.' => 'Để chăm sóc hậu mãi, cập nhật hệ thống và hỗ trợ kỹ thuật.',
    'ການຮັກສາຄວາມປອດໄພຂອງຂໍ້ມູນຮ້ານຄ້າ' => 'Bảo mật dữ liệu cửa hàng',
    'ຂໍ້ມູນສິນຄ້າ, ສະຕັອກ, ລາຍຊື່ລູກຄ້າ ແລະ ຍອດຂາຍໃນລະບົບ POS ຖືກເກັບຮັກສາເປັນຄວາມລັບສູງສຸດຂອງຮ້ານຄ້າ.' => 'Dữ liệu sản phẩm, kho, danh sách khách và doanh số trong POS được giữ bí mật tuyệt đối.',
    'ບໍ່ມີການເປີດເຜີຍ, ຈຳໜ່າຍ ຫຼື ສົ່ງຕໍ່ຂໍ້ມູນຂອງລູກຄ້າໃຫ້ບຸກຄົນທີສາມໂດຍບໍ່ໄດ້ຮັບອະນຸຍາດ.' => 'Không tiết lộ, bán hoặc chuyển dữ liệu khách hàng cho bên thứ ba khi chưa được phép.',
    'ສິດທິຂອງລູກຄ້າ ແລະ ຊ່ອງທາງຕິດຕໍ່' => 'Quyền của khách hàng và kênh liên hệ',
    'ລູກຄ້າສາມາດຕິດຕໍ່ທີມງານເພື່ອຂໍກວດສອບ, ແກ້ໄຂ ຫຼື ລຶບຂໍ້ມູນການຕິດຕໍ່ຂອງຕົນເອງໄດ້ທຸກເວລາ ໃນເວລາທຳການ ຈັນ–ເສົາ 8:30–17:00:' => 'Bạn có thể liên hệ để xem, sửa hoặc xóa thông tin liên hệ trong giờ làm việc, Thứ 2–Thứ 7, 8:30–17:00:',
    'ໂທລະສັບ (ຄຣິກເພື່ອໂທເລີຍ):' => 'Điện thoại (nhấn để gọi):',
    'ຂອບເຂດການໃຫ້ບໍລິການ' => 'Phạm vi dịch vụ',
    '%s ໃຫ້ບໍລິການພັດທະນາ ແລະ ຕິດຕັ້ງລະບົບຂາຍໜ້າຮ້ານ (POS), ຈຳໜ່າຍອຸປະກອນ POS ຄົບຊຸດ ແລະ ພັດທະນາເວັບໄຊ ສຳລັບຮ້ານຄ້າ ແລະ ທຸລະກິດໃນ ສປປ ລາວ.' => '%s phát triển và lắp đặt hệ thống POS, bán thiết bị POS trọn bộ và phát triển website cho cửa hàng, doanh nghiệp tại CHDCND Lào.',
    'ຕິດຕັ້ງລະບົບ ແລະ ຕັ້ງຄ່າອຸປະກອນພ້ອມໃຊ້ງານ ໂດຍທີມງານຜູ້ຊ່ຽວຊານ.' => 'Chuyên viên lắp đặt hệ thống và cấu hình thiết bị sẵn sàng sử dụng.',
    'ຝຶກອົບຮົມການໃຊ້ງານໃຫ້ເຈົ້າຂອງຮ້ານ ແລະ ພະນັກງານ ພ້ອມຄູ່ມືພາສາລາວ.' => 'Đào tạo cho chủ cửa hàng và nhân viên, kèm sổ tay tiếng Lào.',
    'ໃຫ້ຄຳປຶກສາ ແລະ ຊ່ວຍເຫຼືອດ້ານເຕັກນິກໃນເວລາທຳການ ຈັນ–ເສົາ 8:30–17:00.' => 'Tư vấn và hỗ trợ kỹ thuật trong giờ làm việc, Thứ 2–Thứ 7, 8:30–17:00.',
    'ການສອບຖາມລາຄາ ແລະ ການສັ່ງຊື້' => 'Hỏi giá và đặt hàng',
    'ລາຄາສິນຄ້າ, ອຸປະກອນ POS ແລະ ແພັກເກດລະບົບ ແມ່ນບໍ່ສະແດງຢູ່ໜ້າເວັບໄຊ — ລູກຄ້າສາມາດຕິດຕໍ່ສອບຖາມລາຄາ ແລະ ຂໍໃບສະເໜີລາຄາໂດຍກົງນຳທີມງານ ເພື່ອຮັບຂໍ້ສະເໜີທີ່ເໝາະສົມກັບທຸລະກິດ.' => 'Giá sản phẩm, thiết bị POS và gói hệ thống không hiển thị trên website — vui lòng liên hệ trực tiếp để nhận giá và báo giá phù hợp.',
    'ທຸກຄຳສັ່ງຊື້ ຈະມີພະນັກງານຢືນຢັນລາຍການອຸປະກອນ ແລະ ສະຖານທີ່ຈັດສົ່ງ/ຕິດຕັ້ງກ່ອນທຸກຄັ້ງ.' => 'Mọi đơn hàng đều được nhân viên xác nhận danh sách thiết bị và địa điểm giao/lắp đặt trước.',
    'ການຕິດຕັ້ງ ແລະ ການຝຶກອົບຮົມ' => 'Lắp đặt và đào tạo',
    'ບໍລິການຕິດຕັ້ງເຖິງສະຖານທີ່ ຫຼື ຜ່ານລະບົບອອນລາຍ (Remote) ຕາມຄວາມສະດວກຂອງລູກຄ້າ.' => 'Lắp đặt tận nơi hoặc từ xa, tùy bạn thuận tiện.',
    'ສອນການໃຊ້ງານຕັ້ງແຕ່ການເພີ່ມສິນຄ້າ, ການຂາຍໜ້າຮ້ານ, ການຕັດສະຕັອກ ຈົນເຖິງການເບິ່ງລາຍງານຍອດຂາຍ.' => 'Hướng dẫn từ thêm sản phẩm, bán hàng, quản lý kho đến xem báo cáo doanh số.',
    'ການຮັບປະກັນອຸປະກອນ ແລະ ການດູແລຫຼັງການຂາຍ' => 'Bảo hành thiết bị và chăm sóc hậu mãi',
    'ອຸປະກອນ POS ທຸກຊະນິດມີການຮັບປະກັນຕາມເງື່ອນໄຂມາດຕະຖານ (ກໍລະນີເກີດຈາກຄວາມຜິດພາດຂອງໂຮງງານຜະລິດ) ພ້ອມບໍລິການກວດເຊັກ ແລະ ແກ້ໄຂ.' => 'Mọi thiết bị POS được bảo hành theo tiêu chuẩn (lỗi do nhà sản xuất), kèm kiểm tra và sửa chữa.',
