    'ຈໍຂາຍໜ້າຮ້ານສຳຜັດງ່າຍ, ຈັດການອໍເດີ, ຕັດສະຕັອກ ແລະ ພິມບິນຄົບວົງຈອນ' => 'Màn hình cảm ứng, quản lý order, kho và in hóa đơn trọn gói',
