    'ທີມງານກວດສະລິບ ແລະ ຢືນຢັນອໍເດີ ແລ້ວແຈ້ງເລກໃບຝາກເຄື່ອງໃນໜ້າ "ອໍເດີຂອງຂ້ອຍ"' => 'Chúng tôi kiểm tra biên lai, xác nhận đơn và cập nhật mã vận đơn tại "Đơn hàng của tôi"',
