    'ບໍ່ຕ້ອງກັງວົນເລື່ອງລາຄາ — ພຽງແຕ່ຝາກຊື່ ແລະ ເບີ WhatsApp ໄວ້ ທີມງານຈະສົ່ງລາຄາພິເສດພ້ອມຮູບສິນຄ້າຕົວຈິງໃຫ້ເບິ່ງກ່ອນຕັດສິນໃຈຊື້.' => 'Đừng lo về giá — chỉ cần để lại tên và số WhatsApp, chúng tôi sẽ gửi giá đặc biệt kèm ảnh thật trước khi bạn quyết định.',
    'ຝາກເບີ ຫຼື ທັກແຊັດຖາມລາຄາ' => 'Để lại số hoặc nhắn tin hỏi giá',
