    'ລະບຸທີ່ຢູ່ຈັດສົ່ງ ແລະ ບໍລິສັດຂົນສົ່ງໄວ້ລ່ວງໜ້າ (ບໍ່ບັງຄັບ — ແຈ້ງຕອນຕົກລົງລາຄາແລ້ວກໍໄດ້)' => 'Nhập trước địa chỉ và đơn vị vận chuyển (không bắt buộc — có thể báo sau khi chốt giá)',
