    'ເຊັ່ນ: ສາຂາ ດົງໂດກ, ສາຂາ ປາກເຊ...' => 'VD: chi nhánh Dongdok, chi nhánh Pakse...',
    'ລາຍລະອຽດທີ່ຢູ່ເພີ່ມເຕີມ' => 'Chi tiết địa chỉ thêm',
    'ເຊັ່ນ: ຮ່ອມ, ຈຸດສັງເກດ...' => 'VD: hẻm, điểm mốc...',
    'ຍັງບໍ່ມີການເກັບເງິນໃນຂັ້ນຕອນນີ້ — ທີມງານຈະຕິດຕໍ່ແຈ້ງລາຄາພິເສດໃຫ້ທ່ານທາງ WhatsApp / ໂທລະສັບ ທັນທີ.' => 'Chưa thu tiền ở bước này — đội ngũ sẽ liên hệ báo giá đặc biệt qua WhatsApp / điện thoại ngay.',
