    'ລົງທະບຽນຫຼາຍເກີນໄປຈາກເຄື່ອງນີ້ ກະລຸນາລອງໃໝ່ໃນ 1 ຊົ່ວໂມງ' => 'Đăng ký quá nhiều từ thiết bị này, vui lòng thử lại sau 1 giờ',
