    'ຕິດຕັ້ງຟຣີ ສອນໃຊ້ງານໃຫ້ຟຣີ ແລະ ຮັບປະກັນ' => 'Lắp đặt, hướng dẫn miễn phí và bảo hành',
    'ທີມງານຕັ້ງຄ່າ ຕິດຕັ້ງຟຣີ ສອນໃຊ້ງານໃຫ້ຟຣີ ແລະ ດູແລຫຼັງການຂາຍຕະຫຼອດອາຍຸການໃຊ້ງານ.' => 'Đội ngũ cài đặt, lắp đặt và hướng dẫn miễn phí, hỗ trợ sau bán hàng trọn đời.',
