    'ໂປຣແກຣມ POS ລິຂະສິດແທ້ ໃຊ້ງານຕະຫຼອດຊີບ (ບໍ່ມີຄ່າລາຍເດືອນ)' => 'Bản quyền POS chính hãng trọn đời (không phí hàng tháng)',
    'ຮອງຮັບ 1 ຈຸດຂາຍ (ສາມາດເພີ່ມຈຸດຂາຍໄດ້)' => 'Hỗ trợ 1 quầy (có thể thêm)',
