    'ກະລຸນາເພີ່ມອີເມວໃນຂໍ້ມູນຕິດຕໍ່ກ່ອນ — ລະຫັດຜ່ານໃໝ່ຈະສົ່ງໄປອີເມວ' => 'Vui lòng thêm email trong Thông tin liên hệ — mật khẩu mới gửi qua email',
    'ຂໍລະຫັດຜ່ານໃໝ່ຫຼາຍເກີນໄປ ກະລຸນາກວດອີເມວ ຫຼື ລອງໃໝ່ໃນ 1 ຊົ່ວໂມງ' => 'Yêu cầu quá nhiều — kiểm tra email hoặc thử lại sau 1 giờ',
    'ສົ່ງລະຫັດຜ່ານໃໝ່ໄປທີ່ %s ແລ້ວ — ໃຊ້ລະຫັດນັ້ນເຂົ້າສູ່ລະບົບໄດ້ເລີຍ ຫຼື ປ້ອນເປັນລະຫັດເກົ່າເພື່ອຕັ້ງລະຫັດຂອງທ່ານເອງ' => 'Đã gửi mật khẩu mới tới %s — dùng để đăng nhập hoặc nhập làm mật khẩu cũ để đặt mật khẩu riêng',
    'ເພີ່ມອີເມວໃນ "ຂໍ້ມູນຕິດຕໍ່" ກ່ອນ ຈຶ່ງຮັບແຈ້ງເຕືອນໄດ້' => 'Thêm email trong "Thông tin liên hệ" để nhận thông báo',
    'ລືມລະຫັດຜ່ານ' => 'Quên mật khẩu',
    'ປ້ອນອີເມວທີ່ໃຊ້ສະໝັກບັນຊີນີ້ — ຖ້າຖືກຕ້ອງ ລະບົບຈະສົ່ງລະຫັດຜ່ານໃໝ່ໄປອີເມວນັ້ນ ແລ້ວໃຊ້ເຂົ້າສູ່ລະບົບໄດ້ເລີຍ' => 'Nhập email đã đăng ký tài khoản này — nếu đúng, hệ thống sẽ gửi mật khẩu mới tới email đó để đăng nhập',
    'ສົ່ງລະຫັດຜ່ານໃໝ່' => 'Gửi mật khẩu mới',
