    'ກະລຸນາປ້ອນອີເມວທີ່ໃຊ້ສະໝັກບັນຊີ' => 'Vui lòng nhập email đã đăng ký',
    'ອີເມວບໍ່ຖືກຕ້ອງ — ກະລຸນາປ້ອນອີເມວທີ່ໃຊ້ສະໝັກບັນຊີນີ້' => 'Email không đúng — vui lòng nhập email đã đăng ký tài khoản này',
    'ປ້ອນອີເມວຜິດຫຼາຍເກີນໄປ ກະລຸນາລອງໃໝ່ໃນ 1 ຊົ່ວໂມງ' => 'Nhập sai email quá nhiều lần — thử lại sau 1 giờ',
    'ຢຸດຊົ່ວຄາວ' => 'Tạm dừng',
